import React, { useState, useEffect } from "react"
import Fade from "./animations/Fade"
import { Carousel } from "react-bootstrap"
import { useLanguage } from "../contexts/LanguageContext"
import data, { getText } from "../data"
import "../styles/robotlearning.scss"

const RobotLearning = () => {
  const { language } = useLanguage();
  const [activeIndex, setActiveIndex] = useState(0);
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth <= 768);
    };
    checkMobile();
    window.addEventListener("resize", checkMobile);
    return () => window.removeEventListener("resize", checkMobile);
  }, []);

  const handleCarouselSelect = (selectedIndex) => {
    setActiveIndex(selectedIndex);
  };

  return (
    <div className="section" id="robot-learning">
      <div className="container">
        <Fade bottom cascade distance="20px">
          <h1>{getText(data.sections.robotLearning, language)}</h1>
        </Fade>

        <div className="robotlearning-wrapper">
          <Carousel
            className="robotlearning-carousel"
            activeIndex={activeIndex}
            onSelect={handleCarouselSelect}
            interval={5000}
            pause={false}
            touch={true}
            indicators={!isMobile}
            controls={true}
            keyboard={false}
            slide={true}
            wrap={true}
            variant="dark"
          >
            {data.robotLearningVideos.map((video, index) => {
              const title = getText(video.title, language);
              const description = getText(video.description, language);
              const showDescription = description && description.trim().toLowerCase() !== title.trim().toLowerCase();

              return (
                <Carousel.Item key={video.id || index}>
                  <div className="video-container">
                    <video
                      className="d-block"
                      src={video.mediaSrc}
                      muted
                      autoPlay={index === activeIndex}
                      loop
                      playsInline
                      preload="metadata"
                      controls
                    />
                  </div>
                  <Carousel.Caption className="carousel-caption">
                    <h3>{title}</h3>
                    {showDescription && <p>{description}</p>}
                  </Carousel.Caption>
                </Carousel.Item>
              )
            })}
          </Carousel>
        </div>
      </div>
    </div>
  )
}

export default RobotLearning
